CREATE TABLE rrt_orders(id integer PRIMARY KEY, note text, extra integer);
INSERT INTO rrt_orders VALUES (1, 'a', 7), (2, 'b', 8);
SELECT ROW(1, 'x', 3)::rrt_orders, pg_typeof(ROW(1, 'x', 3)::rrt_orders);
SELECT ('(3,c,9)'::rrt_orders).note, ('(3,c,9)'::rrt_orders).*;
SELECT o, pg_typeof(o) FROM rrt_orders o ORDER BY id;
SELECT o = ROW(1, 'a', 7)::rrt_orders, o < ROW(2, NULL, NULL)::rrt_orders FROM rrt_orders o ORDER BY id;
SELECT ROW(1, NULL, NULL)::rrt_orders = ROW(1, NULL, NULL)::rrt_orders;
SELECT ROW(1, NULL, NULL)::rrt_orders IS NOT DISTINCT FROM ROW(1, NULL, NULL)::rrt_orders;
SELECT array_agg(o ORDER BY id), pg_typeof(array_agg(o)) FROM rrt_orders o;
SELECT '{"(1,x,2)"}'::rrt_orders[];
SELECT ROW(1, 'x')::rrt_orders;
SELECT json_populate_record(NULL::rrt_orders, '{"id": 5, "note": "q"}');
CREATE FUNCTION rrt_row(i integer) RETURNS rrt_orders LANGUAGE sql AS 'SELECT * FROM rrt_orders WHERE id = i';
CREATE FUNCTION rrt_scaled(o rrt_orders) RETURNS integer LANGUAGE plpgsql AS $$BEGIN RETURN o.id * 10; END$$;
CREATE FUNCTION rrt_all() RETURNS SETOF rrt_orders LANGUAGE sql AS 'SELECT * FROM rrt_orders ORDER BY id';
SELECT rrt_row(1), (rrt_row(2)).note;
SELECT rrt_scaled(o) FROM rrt_orders o ORDER BY 1;
SELECT * FROM rrt_all();
SELECT rrt_all();
SELECT pg_get_function_arguments('rrt_scaled'::regproc), pg_get_function_result('rrt_row'::regproc);
DROP TABLE rrt_orders;
CREATE TABLE rrt_holder(h integer, o rrt_orders, oa rrt_orders[]);
INSERT INTO rrt_holder VALUES (1, ROW(1, 'a', 7), ARRAY[ROW(2, 'b', 8)::rrt_orders]);
INSERT INTO rrt_holder VALUES (2, ROW(1, 'a'));
ALTER TABLE rrt_orders ADD COLUMN q1 integer;
ALTER TABLE rrt_orders ADD COLUMN q2 integer DEFAULT 5;
ALTER TABLE rrt_orders ALTER COLUMN extra TYPE bigint;
ALTER TABLE rrt_orders ADD COLUMN self rrt_orders;
ALTER TABLE rrt_orders ADD COLUMN nested rrt_holder;
ALTER TABLE rrt_orders DROP COLUMN extra;
ALTER TABLE rrt_orders RENAME COLUMN note TO memo;
INSERT INTO rrt_holder VALUES (3, '(3,c,)');
SELECT * FROM rrt_holder ORDER BY h;
SELECT (o).memo, (oa[1]).memo, pg_typeof(o) FROM rrt_holder WHERE h = 1;
SELECT h FROM rrt_holder WHERE o = ROW(1, 'a', NULL)::rrt_orders;
SELECT format_type(atttypid, atttypmod) FROM pg_attribute WHERE attrelid = 'rrt_holder'::regclass AND attnum > 1 ORDER BY attnum;
ALTER TABLE rrt_orders DROP COLUMN zz;
ALTER TABLE rrt_orders RENAME TO rrt_sales;
SELECT pg_get_function_result('rrt_row'::regproc);
DROP FUNCTION rrt_row(integer), rrt_scaled(rrt_sales), rrt_all();
DROP TABLE rrt_sales;
DROP TABLE rrt_holder, rrt_sales;
